import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={banner:new URL('./reference-redraw-banner.png',import.meta.url).href,power:new URL('./reference-redraw-power.png',import.meta.url).href,back:new URL('./reference-redraw-back.png',import.meta.url).href};export function addStickers(host){const result=[];for(const face of['banner','power','back']){const v=spec.labels[face],p=[...v.position];if(face!=='back')p[2]+=.08;result.push(...printedArtwork(host,{target:host.typecToGroveAssembly.labels[face],url:sources[face],size:v.size,position:p,face:face==='back'?'back':'front',depth:.12,name:'TypeC to Grove own U151 '+face+' reference redraw',artworkKind:'reference-redraw'})??[]);}return result;}
